// orders.js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* env vars
const router = express.Router();

const encodeCursor = (row) =>
  Buffer.from(JSON.stringify([row.cursor_ts, row.id])).toString('base64url');

function decodeCursor(s) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(s, 'base64url').toString());
    if (typeof ts === 'string' && ['string', 'number'].includes(typeof id)) return [ts, id];
  } catch {}
  return null;
}

router.get('/orders', async (req, res, next) => {
  const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

  let where = '';
  const params = [limit + 1]; // one extra row tells us whether there's a next page
  if (req.query.cursor !== undefined) {
    const cursor = decodeCursor(req.query.cursor);
    if (!cursor) return res.status(400).json({ error: 'invalid cursor' });
    where = 'WHERE (created_at, id) < ($2::timestamptz, $3)';
    params.push(...cursor);
  }

  try {
    // created_at::text keeps microseconds; a JS Date would truncate to ms and skip/repeat rows
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_ts
         FROM orders
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      params
    );

    const page = rows.slice(0, limit);
    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: rows.length > limit ? encodeCursor(page[page.length - 1]) : null,
    });
  } catch (err) {
    // class 22 = data exception: well-formed cursor carrying a bad timestamp/id
    if (err.code?.startsWith('22')) return res.status(400).json({ error: 'invalid cursor' });
    next(err);
  }
});

module.exports = router;

if (require.main === module) {
  const assert = require('node:assert');
  const row = { cursor_ts: '2026-10-08 12:00:00.123456+00', id: '42' };
  assert.deepStrictEqual(decodeCursor(encodeCursor(row)), [row.cursor_ts, row.id]);
  for (const bad of ['', 'garbage', 'bnVsbA', 'WzEsMl0']) assert.strictEqual(decodeCursor(bad), null);
  console.log('ok');
}
